DROP TABLE IF EXISTS `grn_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `grn_items` (
  `grn_item_id` int(11) NOT NULL AUTO_INCREMENT,
  `grn_id` int(11) NOT NULL,
  `po_item_id` int(11) DEFAULT NULL COMMENT 'Links back to the PO line; NULL for direct receipts',
  `material_id` int(11) NOT NULL,
  `material_name` varchar(200) NOT NULL COMMENT 'Snapshot of name at GRN time',
  `unit` varchar(50) NOT NULL DEFAULT 'Nos',
  `ordered_quantity` decimal(12,2) NOT NULL DEFAULT 0.00,
  `received_quantity` decimal(12,2) NOT NULL,
  `accepted_quantity` decimal(12,2) NOT NULL,
  `rejected_quantity` decimal(12,2) NOT NULL DEFAULT 0.00,
  `damaged_quantity` decimal(12,2) NOT NULL DEFAULT 0.00,
  `short_quantity` decimal(12,2) NOT NULL DEFAULT 0.00,
  `unit_rate` decimal(15,2) NOT NULL DEFAULT 0.00 COMMENT 'Rate at time of receipt',
  `total_value` decimal(15,2) GENERATED ALWAYS AS (`accepted_quantity` * `unit_rate`) STORED,
  `remarks` text DEFAULT NULL,
  PRIMARY KEY (`grn_item_id`),
  KEY `grn_id` (`grn_id`),
  KEY `material_id` (`material_id`),
  CONSTRAINT `grn_items_ibfk_1` FOREIGN KEY (`grn_id`) REFERENCES `goods_receipt_notes` (`grn_id`) ON DELETE CASCADE,
  CONSTRAINT `grn_items_ibfk_2` FOREIGN KEY (`material_id`) REFERENCES `materials` (`material_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
