INSERT INTO `terms_templates` VALUES (1,'Standard Construction Contract Terms',NULL,NULL,NULL,NULL,'1. Payment terms: 30 days net from invoice date.\n2. All works to strictly follow local municipality guidelines and HSE standards.\n3. Retention rate of 5% applies until final completion.',1,1,NULL,NULL,'2026-09-28 09:14:51','2026-09-28 09:14:51'),(2,'Subcontractor Billing & Progress Terms',NULL,NULL,NULL,NULL,'1. Monthly progress billing against certified milestone completion.\n2. All safety compliance certificates required prior to payment release.',1,1,NULL,NULL,'2026-09-28 09:14:51','2026-09-28 09:14:51'),(3,'Civil & MEP Works General Terms',NULL,NULL,NULL,NULL,'1. Materials subject to on-site quality inspection and approval.\n2. Defect liability period is 12 months from handover date.',1,1,NULL,NULL,'2026-09-28 09:14:51','2026-09-28 09:14:51'),(281,'Payment Terms - Milestone Based','Standard 4-stage payment terms',NULL,NULL,NULL,'',0,1,NULL,NULL,'2026-10-01 11:17:59','2026-10-01 11:17:59'),(358,'DEMO-T&C-001: Milestone Payment Schedule',NULL,NULL,NULL,NULL,'1. 10% Advance mobilization payment against bank guarantee.\n2. Progress claims submitted monthly against approved joint measurement sheets.\n3. Payment due within 30 calendar days from invoice certification.\n4. 5% retention deducted from each claim, released upon DLP expiry.',1,1,NULL,NULL,'2026-10-03 05:44:19','2026-10-03 05:44:19'),(359,'DEMO-T&C-002: Project Timeline & Milestone Schedule',NULL,NULL,NULL,NULL,'1. Contractor commits to project completion according to the approved baseline CPM schedule.\n2. Weekly progress reviews held every Thursday on site.\n3. Milestone slips exceeding 10 days trigger an expedited recovery schedule at no cost to client.',1,1,NULL,NULL,'2026-10-03 05:44:19','2026-10-03 05:44:19'),(360,'DEMO-T&C-003: Material Quality & Price Variation',NULL,NULL,NULL,NULL,'1. All steel, cement and RMC must carry manufacturer MTC and third-party laboratory test reports.\n2. Fuel and major raw material escalation applies only if benchmark index shifts by over +/-10%.\n3. Defective material must be removed from site within 24 hours.',1,1,NULL,NULL,'2026-10-03 05:44:19','2026-10-03 05:44:19'),(361,'DEMO-T&C-004: Extension of Time & Force Majeure',NULL,NULL,NULL,NULL,'1. Unforeseen geological anomalies or client design revisions qualify for formal EOT without penalty.\n2. Formal EOT claims must be lodged in writing within 7 calendar days of the event.\n3. Force majeure covers natural disasters, civil unrest, and statutory site embargoes.',1,1,NULL,NULL,'2026-10-03 05:44:19','2026-10-03 05:44:19'),(362,'DEMO-T&C-005: Warranty & Defect Liability Period (DLP)',NULL,NULL,NULL,NULL,'1. 12 months comprehensive DLP commences from the date of final Practical Completion Certificate.\n2. Structural integrity guaranteed for 10 years per statutory building codes.\n3. Snagging works must be resolved within 14 working days of notification.',1,1,NULL,NULL,'2026-10-03 05:44:19','2026-10-03 05:44:19'),(363,'DEMO-T&C-006: Occupational Health, Safety & Environment',NULL,NULL,NULL,NULL,'1. Zero Harm Policy: Full PPE compliance mandatory for all personnel entering the site.\n2. Qualified HSE officer on duty at all times during active construction.\n3. Tool-box talks conducted daily prior to commencement of shifts.',1,1,NULL,NULL,'2026-10-03 05:44:19','2026-10-03 05:44:19'),(364,'DEMO-T&C-007: QA/QC Quality Assurance Protocols',NULL,NULL,NULL,NULL,'1. Work procedures must strictly adhere to project specification document and IS/BS codes.\n2. Concrete pouring prohibited without formal Inspection Request (IR) sign-off.\n3. Non-conformance reports (NCR) must be rectified and re-inspected.',1,1,NULL,NULL,'2026-10-03 05:44:19','2026-10-03 05:44:19'),(365,'DEMO-T&C-008: Site Access, Working Hours & Logistics',NULL,NULL,NULL,NULL,'1. Heavy vehicles permitted between 08:00 and 19:00 hours per local municipality bylaws.\n2. Secure contractor storage yard and site offices provided within project perimeter.\n3. Temporary site power and water connection arranged by principal contractor.',1,1,NULL,NULL,'2026-10-03 05:44:19','2026-10-03 05:44:19'),(366,'DEMO-T&C-009: Change Orders & Variations Protocol',NULL,NULL,NULL,NULL,'1. Any deviations or extra works require a prior written Variation Order signed by client rep.\n2. Rates for extra items derived from contract bill of quantities or negotiated fair market rate.\n3. Unauthorized extra works will not be compensated.',1,1,NULL,NULL,'2026-10-03 05:44:19','2026-10-03 05:44:19'),(367,'DEMO-T&C-010: Final Handover & As-Built Documentation',NULL,NULL,NULL,NULL,'1. Final handover contingent upon local authority completion certificates (BCC / Civil Defence).\n2. Three hard copies plus digital CAD/BIM As-Built drawings must be handed over.\n3. Comprehensive Operations & Maintenance (O&M) manuals provided for all MEP gear.',1,1,NULL,NULL,'2026-10-03 05:44:19','2026-10-03 05:44:19'),(620,'test','test',NULL,NULL,NULL,'',1,2,1,1,'2026-10-06 09:32:16','2026-10-06 09:32:36'),(621,'Standard Construction Contract Terms',NULL,NULL,NULL,NULL,'1. Payment terms: 30 days net from invoice date.\n2. All works to strictly follow local municipality guidelines and HSE standards.\n3. Retention rate of 5% applies until final completion.',1,1,NULL,NULL,'2026-10-06 10:35:05','2026-10-06 10:35:05'),(622,'Subcontractor Billing & Progress Terms',NULL,NULL,NULL,NULL,'1. Monthly progress billing against certified milestone completion.\n2. All safety compliance certificates required prior to payment release.',1,1,NULL,NULL,'2026-10-06 10:35:05','2026-10-06 10:35:05'),(623,'Civil & MEP Works General Terms',NULL,NULL,NULL,NULL,'1. Materials subject to on-site quality inspection and approval.\n2. Defect liability period is 12 months from handover date.',1,1,NULL,NULL,'2026-10-06 10:35:05','2026-10-06 10:35:05'),(624,'Standard Construction Contract Terms',NULL,NULL,NULL,NULL,'1. Payment terms: 30 days net from invoice date.\n2. All works to 